<script setup>
import { computed, onMounted, ref } from 'vue'
import { useAuthStore } from '@/stores/authStore'
import { sheetApi } from '@/services/api'

const auth = useAuthStore()

const sheets = ref([])
const loading = ref(true)
const error = ref('')

onMounted(async () => {
  try {
    sheets.value = (await sheetApi.mine()) ?? []
  } catch (err) {
    error.value = err.message
  } finally {
    loading.value = false
  }
})

const greeting = computed(() => {
  const hour = new Date().getHours()
  if (hour < 12) return 'สวัสดีตอนเช้า'
  if (hour < 17) return 'สวัสดีตอนบ่าย'
  return 'สวัสดีตอนเย็น'
})

const countBy = (status) =>
  sheets.value.filter((s) => String(s.status).toUpperCase() === status).length

const statCards = computed(() => [
  { key: 'total', label: 'ชีททั้งหมด', value: sheets.value.length, hint: 'ที่คุณส่งเข้าระบบ' },
  { key: 'approved', label: 'อนุมัติแล้ว', value: countBy('APPROVED'), hint: 'พร้อมให้ดาวน์โหลด', tone: 'positive' },
  { key: 'pending', label: 'รอตรวจสอบ', value: countBy('PENDING'), hint: 'กำลังรอผู้ดูแล', tone: 'warning' },
  {
    key: 'downloads',
    label: 'ยอดดาวน์โหลด',
    value: sheets.value.reduce((sum, s) => sum + (s.downloadCount ?? 0), 0),
    hint: 'จากชีทของคุณ'
  }
])

const recentSheets = computed(() =>
  [...sheets.value]
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))
    .slice(0, 5)
)

const resourceCards = [
  {
    label: 'Lectures',
    desc: 'View lecture materials by course, year, and instructor.',
    to: '/dashboard/lec',
    tone: 'green'
  },
  {
    label: 'Sheets',
    desc: 'Browse worksheets, summaries, and shared study notes.',
    to: '/dashboard/sheet',
    tone: 'sage'
  },
  {
    label: 'Exercises',
    desc: 'Practice materials grouped by subject.',
    to: '/dashboard/sheet',
    tone: 'white'
  },
  {
    label: 'Exams',
    desc: 'Past examinations and review documents.',
    to: '/dashboard/sheet',
    tone: 'dark'
  }
]

const quickActions = [
  {
    label: 'Search',
    desc: 'Find resources by course or title',
    to: '/dashboard/sheet',
    icon: 'M21 21l-4.3-4.3 M10.5 18a7.5 7.5 0 1 1 0-15 7.5 7.5 0 0 1 0 15z'
  },
  {
    label: 'Upload',
    desc: 'Send a file for admin approval',
    to: '/dashboard/upload',
    icon: 'M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2 M12 15V4 M8 8l4-4 4 4'
  },
  {
    label: 'My Upload Requests',
    desc: 'Track approval status and details',
    to: '/dashboard/requests',
    icon: 'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M9 13h6 M9 17h4'
  },
  {
    label: 'Notifications',
    desc: 'Review admin decisions',
    to: '/dashboard/profile',
    icon: 'M18 8a6 6 0 1 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4'
  }
]

const shortcuts = [
  {
    label: 'อัปโหลดชีท',
    desc: 'เพิ่มชีทใหม่เข้าสู่คลัง',
    to: '/dashboard/upload',
    icon: 'M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2 M12 15V4 M8 8l4-4 4 4'
  },
  {
    label: 'ชีทของฉัน',
    desc: 'ดูสถานะและยอดดาวน์โหลด',
    to: '/dashboard/sheet',
    icon: 'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M9 13h6 M9 17h4'
  },
  {
    label: 'Lecture',
    desc: 'เอกสารประกอบการเรียน',
    to: '/dashboard/lec',
    icon: 'M12 7v14 M3 5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v14a2 2 0 0 0-2-2H5a2 2 0 0 1-2-2V5z M21 5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v14a2 2 0 0 1 2-2h4a2 2 0 0 0 2-2V5z'
  },
  {
    label: 'โปรไฟล์',
    desc: 'จัดการข้อมูลบัญชี',
    to: '/dashboard/profile',
    icon: 'M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2 M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z'
  }
]

function formatDate(value) {
  if (!value) return '—'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return date.toLocaleDateString('th-TH', { day: 'numeric', month: 'short', year: 'numeric' })
}

function statusLabel(status) {
  const map = { APPROVED: 'อนุมัติแล้ว', PENDING: 'รอตรวจสอบ', REJECTED: 'ถูกปฏิเสธ' }
  return map[String(status).toUpperCase()] ?? status
}
</script>

<template>
  <div class="home">
    <!-- Welcome hero — polarity-flipped dark band with lime headline -->
    <header class="home-hero">
      <div class="home-hero__text">
        <p class="home-eyebrow">{{ greeting }}</p>
        <h1>{{ auth.user?.username ?? 'ผู้ใช้' }}</h1>
        <p class="home-hero__lead">
          ยินดีต้อนรับกลับสู่ CSIT Sheet — จัดการชีท ติดตามสถานะการตรวจสอบ
          และอัปโหลดเอกสารได้จากที่นี่
        </p>
        <div class="home-hero__actions">
          <RouterLink class="home-btn home-btn--primary" to="/dashboard/upload">
            อัปโหลดชีทใหม่
          </RouterLink>
          <RouterLink class="home-btn home-btn--ghost" to="/dashboard/sheet">
            ดูชีทของฉัน
          </RouterLink>
        </div>
      </div>
      <div class="home-hero__aside" aria-hidden="true">
        <span class="home-hero__count">{{ loading ? '—' : sheets.length }}</span>
        <span class="home-hero__count-label">ชีทของคุณ</span>
      </div>
    </header>

    <section class="learning-resources" aria-label="Learning resources">
      <div class="home-card__head">
        <div>
          <p class="home-eyebrow">Learning Resources</p>
          <h2>Choose what you want to explore.</h2>
        </div>
      </div>
      <div class="resource-grid">
        <RouterLink
          v-for="resource in resourceCards"
          :key="resource.label"
          :to="resource.to"
          class="resource-card"
          :class="`resource-card--${resource.tone}`"
        >
          <span>{{ resource.label }}</span>
          <p>{{ resource.desc }}</p>
        </RouterLink>
      </div>
    </section>

    <!-- Summary stats -->
    <section class="home-stats" aria-label="สรุปข้อมูล">
      <article
        v-for="card in statCards"
        :key="card.key"
        class="home-stat"
        :class="card.tone && `home-stat--${card.tone}`"
      >
        <span class="home-stat__label">{{ card.label }}</span>
        <strong class="home-stat__value">{{ loading ? '—' : card.value }}</strong>
        <span class="home-stat__hint">{{ card.hint }}</span>
      </article>
    </section>

    <div class="home-grid">
      <!-- Recent sheets -->
      <section class="home-card home-recent">
        <div class="home-card__head">
          <h2>ชีทล่าสุด</h2>
          <RouterLink to="/dashboard/sheet" class="home-link">ดูทั้งหมด →</RouterLink>
        </div>

        <p v-if="loading" class="home-muted">กำลังโหลดข้อมูล...</p>
        <p v-else-if="error" class="home-error">{{ error }}</p>

        <div v-else-if="recentSheets.length" class="home-recent__list">
          <div v-for="sheet in recentSheets" :key="sheet.id" class="home-recent__row">
            <div class="home-recent__main">
              <span class="home-recent__title">{{ sheet.title }}</span>
              <span class="home-recent__subject">{{ sheet.subject }}</span>
            </div>
            <div class="home-recent__meta">
              <span
                class="home-pill"
                :class="`home-pill--${String(sheet.status).toLowerCase()}`"
              >
                {{ statusLabel(sheet.status) }}
              </span>
              <span class="home-recent__date">{{ formatDate(sheet.createdAt) }}</span>
            </div>
          </div>
        </div>

        <div v-else class="home-empty">
          <p class="home-empty__title">ยังไม่มีชีท</p>
          <p class="home-muted">เริ่มต้นด้วยการอัปโหลดชีทแรกของคุณ</p>
          <RouterLink class="home-btn home-btn--primary" to="/dashboard/upload">
            อัปโหลดเลย
          </RouterLink>
        </div>
      </section>

      <!-- Quick actions -->
      <aside class="home-card home-actions">
        <div class="home-card__head">
          <h2>ทางลัด</h2>
        </div>
        <RouterLink
          v-for="action in quickActions"
          :key="action.to"
          :to="action.to"
          class="home-action"
        >
          <span class="home-action__icon" aria-hidden="true">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"
              stroke-linecap="round" stroke-linejoin="round">
              <path :d="action.icon" />
            </svg>
          </span>
          <span class="home-action__text">
            <span class="home-action__label">{{ action.label }}</span>
            <span class="home-action__desc">{{ action.desc }}</span>
          </span>
          <span class="home-action__chevron" aria-hidden="true">→</span>
        </RouterLink>
      </aside>
    </div>
  </div>
</template>

